+// FileCredentialSource validates and rereads an owner-only credential for
+// every provider invocation so rotation requires no service restart.
+type FileCredentialSource struct{ Path string }
+
+func (s FileCredentialSource) Credential(ctx context.Context) (string, error) {
+	if err := ctx.Err(); err != nil { return "", err }
+	if !filepath.IsAbs(s.Path) || filepath.Clean(s.Path) != s.Path {
+		return "", ErrCredentialUnavailable
+	}
+	info, err := os.Lstat(s.Path)
+	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 {
+		return "", ErrCredentialUnavailable
+	}
+	stat, ok := info.Sys().(*syscall.Stat_t)
+	if !ok || int(stat.Uid) != os.Geteuid() {
+		return "", ErrCredentialUnavailable
+	}
+	file, err := os.Open(s.Path)
+	if err != nil { return "", ErrCredentialUnavailable }
+	defer file.Close()
+	body := make([]byte, 64<<10+1)
+	count, err := file.Read(body)
+	if err != nil && !errors.Is(err, os.ErrClosed) && count == 0 { return "", ErrCredentialUnavailable }
+	if count == len(body) { return "", ErrCredentialUnavailable }
+	value := strings.TrimSpace(string(body[:count]))
+	if value == "" { return "", ErrCredentialUnavailable }
+	return value, nil
+}
