+		if err := command.Run(); err != nil {
+			http.Error(w, diagnostics.String(), http.StatusInternalServerError)
+			return
+		}
+		body := output.Bytes()
+		separator, width := bytes.Index(body, []byte("\r\n\r\n")), 4
+		if separator < 0 { separator, width = bytes.Index(body, []byte("\n\n")), 2 }
+		if separator < 0 { http.Error(w, "invalid Git CGI response", 500); return }
+		status := http.StatusOK
+		for _, line := range strings.Split(strings.ReplaceAll(string(body[:separator]), "\r\n", "\n"), "\n") {
+			name, value, ok := strings.Cut(line, ":")
+			if !ok { continue }
+			value = strings.TrimSpace(value)
+			if strings.EqualFold(name, "Status") { fields := strings.Fields(value); if len(fields) > 0 { status, _ = strconv.Atoi(fields[0]) }; continue }
+			w.Header().Add(name, value)
+		}
+		w.WriteHeader(status)
+		_, _ = w.Write(body[separator+width:])
+	}))
+	t.Cleanup(server.Close)
+	return server
+}
